import sys

def is_valid_sudoku(board):
    # Check rows
    for row in board:
        seen = set()
        for cell in row:
            if cell != '.':
                if cell in seen:
                    return False
                seen.add(cell)

    # Check columns
    for col in range(9):
        seen = set()
        for row in range(9):
            cell = board[row][col]
            if cell != '.':
                if cell in seen:
                    return False
                seen.add(cell)

    # Check 3x3 sub-boxes
    for box_row in range(3):
        for box_col in range(3):
            seen = set()
            for i in range(3):
                for j in range(3):
                    row = box_row * 3 + i
                    col = box_col * 3 + j
                    cell = board[row][col]
                    if cell != '.':
                        if cell in seen:
                            return False
                        seen.add(cell)

    return True

def main():
    board = []
    for _ in range(9):
        line = sys.stdin.readline().strip()
        row = line.split()
        board.append(row)

    if is_valid_sudoku(board):
        print("true")
    else:
        print("false")

if __name__ == "__main__":
    main()
